    override fun equals(other: Any?): Boolean = other is Vector4fc && x.toBits() == other.x().toBits() && y.toBits() == other.y().toBits() && z.toBits() == other.z().toBits() && w.toBits() == other.w().toBits()
    override fun hashCode(): Int {
        var result = 1
        result = 31 * result + x.toBits()
        result = 31 * result + y.toBits()
        result = 31 * result + z.toBits()
        result = 31 * result + w.toBits()
        return result
    }
    override fun toString(): String = "($x, $y, $z, $w)"
}
